151	  const loading =
152	    health.status === 'loading' ||
153	    sweepState.status === 'loading' ||
154	    nearMisses.status === 'loading';
155	  const signals: OverviewSignal[] = [];
156	
157	  if (health.status === 'ok') signals.push(...healthSignals(health.data));
158	  if (health.status === 'error')
159	    signals.push(sourceErrorSignal('health', 'Workspace health', health.error, '/admin/overview'));
160	
161	  if (sweep) signals.push(...sweepSignals(sweep));
162	  if (sweepState.status === 'error')
163	    signals.push(
164	      sourceErrorSignal(
165	        'sweep',
166	        'The orphan-secret sweep report',
167	        sweepState.error,
168	        '#secret-store',
169	      ),
170	    );
171	
172	  if (nearMisses.status === 'ok') signals.push(...nearMissSignals(nearMisses.data));
173	  if (nearMisses.status === 'error')
174	    signals.push(
175	      sourceErrorSignal('near-misses', 'Trigger env mismatches', nearMisses.error, '/suites'),
176	    );
177	
178	  const ordered = orderSignals(signals);
179	
180	  return (
181	    <Section title="Needs attention">
182	      {loading && <Typography.Text type="secondary">Loading signals…</Typography.Text>}
183	      {!loading && ordered.length === 0 && (
184	        <Typography.Text type="secondary">
185	          Nothing needs attention among the signals below. Only what the health checklist lists is
186	          watched — anything not listed there is unmonitored, not clear.
187	        </Typography.Text>
188	      )}
189	      <Flex vertical gap={12}>
190	        {ordered.map((signal) => (
191	          <SignalRow key={signal.key} signal={signal} />
192	        ))}
193	      </Flex>
194	    </Section>
195	  );
196	}
