202	        <Flex align="center" gap={8} wrap>
203	          <Tag color={signal.tone === 'attention' ? 'red' : 'default'}>
204	            {signal.tone === 'attention' ? 'Needs action' : 'Not monitored'}
205	          </Tag>
206	          <Typography.Text strong>{signal.title}</Typography.Text>
207	        </Flex>
208	        <Typography.Text type="secondary" style={{ fontSize: 12 }}>
209	          {signal.detail}
210	        </Typography.Text>
211	      </Flex>
212	      {signal.to.startsWith('#') ? (
213	        <Typography.Link href={signal.to}>{signal.verb}</Typography.Link>
214	      ) : (
