251	const NOT_CHECKED = { color: 'default', label: 'Not verified this session' };
252	
253	function ChainItem({ chain }: { chain: ReturnType<typeof useAuditChainVerify> }) {
254	  const { state, verify } = chain;
255	  const tag =
256	    state.status === 'done'
