327	function SecretStoreItem({
328	  state,
329	  report,
330	  onRan,
331	}: {
332	  state: AsyncState<SecretSweepReport>;
333	  report: SecretSweepReport | null;
334	  onRan: (report: SecretSweepReport) => void;
335	}) {
336	  const [runState, setRunState] = useState<'idle' | 'running' | 'queued'>('idle');
337	  const [error, setError] = useState<string | null>(null);
338	
339	  const run = async () => {
340	    setRunState('running');
341	    setError(null);
342	    try {
343	      await runSecretSweep();
344	    } catch (err) {
345	      setRunState('idle');
346	      setError(fetchFailure(err).message);
347	      return;
348	    }
349	    const fresh = await awaitSweepRun(report?.ran_at ?? null);
350	    if (fresh) {
351	      onRan(fresh);
352	      setRunState('idle');
353	    } else {
354	      // The enqueue succeeded; the worker just hasn't recorded a report yet. Saying so beats
355	      // showing the previous run's numbers as if they were this run's.
356	      setRunState('queued');
357	    }
358	  };
359	
360	  const tag =
361	    state.status === 'error'
362	      ? { color: 'orange', label: 'Unknown — could not load' }
363	      : !report
364	        ? { color: 'default', label: 'Loading' }
365	        : report.status === 'never_run'
366	          ? { color: 'default', label: 'Never run' }
367	          : report.status === 'skipped' || report.orphan_count === null
368	            ? { color: 'default', label: 'Not enumerated' }
369	            : report.orphan_count > 0
370	              ? { color: 'red', label: `${report.orphan_count} orphan(s)` }
371	              : { color: 'green', label: 'No orphans' };
372	
373	  return (
374	    <HealthItem
375	      id="secret-store"
376	      title="Secret store"
377	      tag={tag}
378	      detail={
379	        <Flex vertical gap={4}>
380	          <span>{sweepDetail(state, report)}</span>
381	          {runState === 'queued' && (
382	            <Alert
383	              type="info"
384	              showIcon
385	              title="Sweep queued"
386	              description="The run was accepted but no new report has landed yet. Refresh this page later to see it — the numbers above are still the previous run's."
387	            />
388	          )}
389	          {error && (
390	            <Alert type="error" showIcon title="Could not start the sweep" description={error} />
391	          )}
392	        </Flex>
393	      }
394	      action={
395	        <Button onClick={run} loading={runState === 'running'}>
396	          Run sweep
397	        </Button>
398	      }
399	    />
400	  );
401	}
402	
403	function sweepDetail(
404	  state: AsyncState<SecretSweepReport>,
405	  report: SecretSweepReport | null,
406	): string {
407	  if (state.status === 'error')
408	    return `${state.error} — the number of unowned secrets is unknown, not zero.`;
409	  if (!report) return 'Reading the last sweep report…';
410	  if (report.status === 'never_run')
411	    return 'No sweep report has ever been recorded, so the number of unowned secrets is unknown — not zero.';
412	  if (report.status === 'skipped' || report.orphan_count === null)
413	    return `The last run recorded no count, so nothing is known about unowned secrets. ${report.error ?? ''}`.trim();
414	  return `${report.orphan_count} unowned secret(s) of ${report.scanned ?? '—'} scanned in ${report.store ?? 'the store'}, recorded ${formatTimestamp(report.ran_at)}. ${report.unknown_age_count ?? 0} could not be dated and ${report.too_young_count ?? 0} were too young to judge.`;
415	}
416	
417	function PollingItem({ state }: { state: AsyncState<AdminHealth> }) {
418	  const action = <Link to="/admin/integrations">Details</Link>;
419	  if (state.status !== 'ok') {
420	    return (
421	      <HealthItem
422	        title="Orchestration polling"
423	        tag={
424	          state.status === 'loading'
425	            ? { color: 'default', label: 'Loading' }
426	            : { color: 'orange', label: 'Unknown — could not load' }
427	        }
428	        detail={
429	          state.status === 'error'
430	            ? `${state.error} — poll staleness is unknown, not on cadence.`
431	            : 'Reading per-connection poll staleness…'
432	        }
433	        action={action}
434	      />
435	    );
436	  }
437	  const rows = state.data.polling;
438	  const bad = rows.filter((r) => r.status === 'stalled' || r.status === 'failing').length;
439	  const unknown = rows.filter((r) => r.status === 'unknown').length;
440	  const tag =
441	    rows.length === 0
442	      ? { color: 'default', label: 'Nothing to poll' }
443	      : bad > 0
444	        ? { color: 'red', label: `${bad} unhealthy` }
445	        : unknown > 0
446	          ? { color: 'default', label: `${unknown} never polled` }
447	          : { color: 'green', label: 'On cadence' };
448	  return (
449	    <HealthItem
450	      title="Orchestration polling"
451	      tag={tag}
452	      detail={
453	        rows.length === 0
454	          ? 'No orchestration connections are configured, so no pipeline completions reach DataQ by polling at all.'
455	          : `${rows.length} connection(s): ${bad} unhealthy, ${unknown} never polled (never polled is unknown, not healthy).`
456	      }
457	      action={action}
458	    />
459	  );
460	}

